package com.aistock.market.alert;
import com.aistock.market.ingestion.CandidateRequestFilter;import org.junit.jupiter.api.Test;import static org.mockito.Mockito.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;import org.springframework.test.web.servlet.setup.MockMvcBuilders;
class AlertBoundaryHttpTest {
 @Test void boundaryIsProtectedOnDirectAndNormalizedPaths()throws Exception{var service=mock(AlertBoundaryService.class);var mvc=MockMvcBuilders.standaloneSetup(new AlertBoundaryController(service)).addFilters(new CandidateRequestFilter("private-service",64)).build();for(String root:new String[]{"/internal/v1/market/","/internal/v1/market;v/"}){mvc.perform(get(root+"alert-boundary/SH600030")).andExpect(status().isUnauthorized());mvc.perform(get(root+"alert-boundary/SH600030").header("X-Service-Token","wrong")).andExpect(status().isUnauthorized());}verifyNoInteractions(service);mvc.perform(get("/internal/v1/market/alert-boundary/SH600030").header("X-Service-Token","private-service")).andExpect(status().isOk());verify(service).get("SH600030");}
}
